#include <iostream>
#include <vector>

class Tank {
public:
    void put(int w) {
        weights.push_back(w);
    }

    int total() const;

private:
    std::vector<int> weights;
};

int Tank::total() const {
    int s = 0;
    for (int i = 0; i < static_cast<int>(weights.size()); i++) {
        s += weights[i];
    }
    return s;
}

int main() {
    int n = 0;
    std::cin >> n;
    Tank t;
    for (int i = 0; i < n; i++) {
        int w = 0;
        std::cin >> w;
        t.put(w);
    }
    std::cout << "总重：" << t.total() << " 克" << std::endl;
    return 0;
}
